import copy,posixpath

def repair_mount(config,source,expected_target,new_target):
    def path(value):
        if not isinstance(value,str) or not value.startswith('/') or '..' in value.split('/') or posixpath.normpath(value)!=value:raise ValueError('normalized absolute mount target required')
        return value
    path(expected_target);path(new_target);configuration=path(config['configuration'])
    if new_target=='/' or configuration==new_target or configuration.startswith(new_target+'/'):raise ValueError('new data mount still obscures configuration')
    matches=[index for index,mount in enumerate(config['mounts']) if mount.get('source')==source]
    if len(matches)!=1:raise ValueError('one approved data source required')
    index=matches[0]
    if config['mounts'][index].get('target')!=expected_target:raise ValueError('stale mount target')
    if any(i!=index and mount.get('target')==new_target for i,mount in enumerate(config['mounts'])):raise ValueError('mount target collision')
    result=copy.deepcopy(config);result['mounts'][index]['target']=new_target
    return result
